{
  "steps": [
    {
      "id": 1,
      "claim": "Total loans taken during college = 4 years × $50,000 per year",
      "evidence": "Problem states $50,000 in loans per year for a 4‑year program",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Total loans amount to $200,000",
      "evidence": "Multiplication from step 1: 4 × 50,000 = 200,000",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Lost earnings while in school = 4 years × $25,000 per year",
      "evidence": "Problem states he would have earned $25k per year if not in school",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 4,
      "claim": "Lost earnings amount to $100,000",
      "evidence": "Multiplication from step 3: 4 × 25,000 = 100,000",
      "weight": 0.15,
      "depends_on": [3]
    },
    {
      "id": 5,
      "claim": "Total amount to recover = loans + lost earnings",
      "evidence": "Add results from steps 2 and 4",
      "weight": 0.10,
      "depends_on": [2, 4]
    },
    {
      "id": 6,
      "claim": "Total amount to recover = $300,000",
      "evidence": "200,000 + 100,000 = 300,000",
      "weight": 0.10,
      "depends_on": [5]
    },
    {
      "id": 7,
      "claim": "Post‑college salary = 3 × $25,000",
      "evidence": "Problem says his degree triples his income",
      "weight": 0.08,
      "depends_on": []
    },
    {
      "id": 8,
      "claim": "Post‑college salary = $75,000 per year",
      "evidence": "3 × 25,000 = 75,000",
      "weight": 0.08,
      "depends_on": [7]
    },
    {
      "id": 9,
      "claim": "Incremental earnings per year = $75,000 – $25,000",
      "evidence": "Difference between new salary and the salary he would have earned without college",
      "weight": 0.07,
      "depends_on": [8]
    },
    {
      "id": 10,
      "claim": "Incremental earnings per year = $50,000",
      "evidence": "75,000 – 25,000 = 50,000",
      "weight": 0.07,
      "depends_on": [9]
    },
    {
      "id": 11,
      "claim": "Years needed to recover $300,000 = $300,000 ÷ $50,000 per year",
      "evidence": "Divide total amount to recover by incremental earnings per year",
      "weight": 0.07,
      "depends_on": [6, 10]
    },
    {
      "id": 12,
      "claim": "Years needed = 6",
      "evidence": "300,000 ÷ 50,000 = 6",
      "weight": 0.07,
      "depends_on": [11]
    }
  ],
  "answer": "6",
  "confidence": 0.97,
  "considered": [
    {
      "answer": "4",
      "reason_rejected": "Using the total post‑college salary (75,000) instead of the incremental gain ignores the $25,000 per year he would have earned anyway; the problem asks for the time to recoup both the loans and the lost earnings, which requires using the net increase of $50,000 per year."
    }
  ]
}
